buildFontFaceBlock: truetype:
@font-face {
    font-family: 'Solo';
    src: url('Solo-Regular.TTF') format('truetype');
    font-weight: normal;
    font-style: normal;
}

buildFontFaceBlock: opentype bold italic:
@font-face {
    font-family: 'Duo';
    src: url('duo-bolditalic.otf') format('opentype');
    font-weight: bold;
    font-style: italic;
}

